#!/usr/bin/env bash
# Watcher cadence carriers: which local config files declare a watcher's poll
# cadence for one home, in which order they apply, and how a watcher launcher
# applies them.
#
# This lib is the single owner of that contract. docs/configuration.md's
# "Watcher cadence carriers" section owns the operator-facing description, and
# bin/fm-arm-command-policy.mjs separately owns which of these paths an
# agent-typed arm command is still permitted to source by hand.
#
# A carrier is `$FM_HOME/config/x-mode.env` (Relay's, generated by
# bin/fm-bootstrap.sh) or any `$FM_HOME/config/check-cadence.d/<name>.env` (the
# extension seam an out-of-tree feature drops its own generated cadence into).
# Carriers are per-home: they are resolved from FM_CONFIG_OVERRIDE when set and
# otherwise from $FM_HOME/config, so a secondmate arming its own watcher never
# inherits the primary's cadence.
#
# ORDER. Carriers are applied so the SMALLEST declared FM_CHECK_INTERVAL is
# applied LAST and therefore wins: a home running several carriers must inherit
# the snappiest one rather than whichever file happened to sort last. Ties and
# files that declare no interval fall back to reverse filename order, so the
# result is deterministic.
#
# ALLOWLIST. A carrier is never executed - not to render an operating block and
# not to arm a watcher. Each file is read by pattern for exactly two keys:
#
#   FM_CHECK_INTERVAL        seconds between the watcher's slow check sweeps
#   FM_STALE_ESCALATE_SECS   idle seconds before a provably-working stale pane
#                            escalates as a possible wedge
#
# Anything else in the file - another variable, a command, a syntax error, an
# `exit` - is ignored rather than run, so a malformed carrier can never take
# watcher supervision down with it. The recognized shape is one line of
# `[export ]<KEY>=<digits>`; a quoted or non-integer value is not a declaration.
#
# PRECEDENCE. A key already carrying a non-empty value in the environment wins
# over every carrier, so an explicit `FM_CHECK_INTERVAL=5 bin/fm-watch-arm.sh`
# (and a command that pre-sourced a carrier itself) keeps that value. Carriers
# fill in only the keys nothing has set yet.

FM_CADENCE_LIB_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
FM_CADENCE_DEFAULT_ROOT="$(cd "$FM_CADENCE_LIB_DIR/.." && pwd)"

# Resolve the config directory carriers live in, the same way every other home-
# scoped script does: an explicit argument wins, then FM_CONFIG_OVERRIDE, then
# this home's own config dir.
fm_cadence_dir() {  # [config-dir]
  local home
  if [ -n "${1:-}" ]; then
    printf '%s\n' "$1"
    return 0
  fi
  home="${FM_HOME:-${FM_ROOT_OVERRIDE:-$FM_CADENCE_DEFAULT_ROOT}}"
  printf '%s\n' "${FM_CONFIG_OVERRIDE:-$home/config}"
}

# The value a carrier declares for one allowlisted key, or empty when it
# declares none. Read by PATTERN, never by sourcing.
fm_cadence_declared() {  # <file> <key>
  sed -n "s/^[[:space:]]*\(export[[:space:]]\{1,\}\)\{0,1\}$2=\([0-9]\{1,\}\).*\$/\2/p" "$1" 2>/dev/null | tail -1
}

# The interval a carrier declares, or 0 when it declares none. Used for ordering.
fm_cadence_interval() {  # <file>
  local n
  n=$(fm_cadence_declared "$1" FM_CHECK_INTERVAL)
  printf '%s' "${n:-0}"
}

# Every active carrier for one home, one absolute path per line, ordered so the
# smallest declared interval comes LAST.
#
# With <include-absent-x-mode> set to 1, x-mode.env is listed even when the file
# does not exist yet. Callers that render an instruction want that (the rendered
# clause is guarded by `[ -f ]`, so naming a not-yet-generated carrier is a
# no-op while dropping it would lose the cadence of a home that generates it
# between render and arm); callers that apply carriers do not, and skip a
# missing file anyway.
fm_cadence_files() {  # [config-dir] [include-absent-x-mode]
  local dir x_mode_env f
  dir=$(fm_cadence_dir "${1:-}")
  x_mode_env="$dir/x-mode.env"
  {
    if [ "${2:-0}" = 1 ] || [ -f "$x_mode_env" ]; then
      printf '%s\t%s\n' "$(fm_cadence_interval "$x_mode_env")" "$x_mode_env"
    fi
    if [ -d "$dir/check-cadence.d" ]; then
      for f in "$dir/check-cadence.d"/*.env; do
        [ -f "$f" ] || continue
        printf '%s\t%s\n' "$(fm_cadence_interval "$f")" "$f"
      done
    fi
    return 0
  } | LC_ALL=C sort -t"$(printf '\t')" -k1,1nr -k2,2r | cut -f2-
}

# Export every allowlisted key this home's carriers declare, in carrier order,
# so a watcher forked after this call inherits the snappiest cadence. Keys
# already set in the environment are left alone.
fm_cadence_apply() {  # [config-dir]
  local dir f key value preset=' '
  dir=$(fm_cadence_dir "${1:-}")
  for key in FM_CHECK_INTERVAL FM_STALE_ESCALATE_SECS; do
    if [ -n "${!key:-}" ]; then
      preset="$preset$key "
    fi
  done
  while IFS= read -r f; do
    [ -n "$f" ] || continue
    [ -f "$f" ] || continue
    for key in FM_CHECK_INTERVAL FM_STALE_ESCALATE_SECS; do
      case "$preset" in
        *" $key "*) continue ;;
      esac
      value=$(fm_cadence_declared "$f" "$key")
      [ -n "$value" ] || continue
      export "$key=$value"
    done
  done <<EOF
$(fm_cadence_files "$dir")
EOF
  return 0
}
